SELECT r.id, r.code, r.name, r.description, r.status, r.created_at, r.updated_at, (SELECT COUNT(*) FROM user_role ur WHERE ur.role_id = r.id) as user_count FROM role r
(r.code LIKE CONCAT('%', #{keyword}, '%') OR r.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.id LIMIT #{limit} OFFSET #{offset}

